#[tokio::test]
async fn existing_signed_cache_keeps_canonical_time_bytes_and_authentication() {
    let codex_home = tempfile::tempdir().expect("temporary cache home");
    let cache = CloudConfigBundleCache::new(AbsolutePathBuf::resolve_path_against_base(
        codex_home.path(),
        "/",
    ));
    for (input, canonical, signature) in LEGACY_FIXTURES {
        let payload: CloudConfigBundleCacheSignedPayload =
            serde_json::from_str(input).expect("old timestamp grammar");
        let payload_bytes = cache_payload_bytes(&payload).expect("canonical payload bytes");
        assert_eq!(payload_bytes, canonical.as_bytes());
        assert!(verify_cache_signature(&payload_bytes, signature));
        let file = CloudConfigBundleCacheFile {
            signed_payload: payload.clone(),
            signature: (*signature).to_string(),
        };
        std::fs::write(
            cache.path(),
            serde_json::to_vec(&file).expect("serialize frozen cache"),
        )
        .expect("write frozen cache");
        assert_eq!(
            cache.load(Some("user-12345"), Some("account-12345")).await,
            Ok(payload),
        );
        let mut tampered = file.signed_payload;
        tampered.cached_at =
            CanonicalUtcTimestamp::parse_legacy("2098-01-01T00:00:00Z").expect("replacement time");
        assert!(!verify_cache_signature(
            &cache_payload_bytes(&tampered).expect("tampered payload bytes"),
            signature,
        ));
    }
}

#[test]
fn cache_clock_preserves_epoch_parts_without_rounding() {
    for (seconds, nanos) in [
        (0, 0),
        (0, 999_999_999),
        (1, 1),
        (2_147_483_648, 123_456_789),
        (8_210_266_876_799, 999_999_999),
    ] {
        let now = cache_now_utc(Ok(Duration::new(seconds, nanos)));
        assert_eq!(
            (now.unix_timestamp(), now.nanosecond(), now.offset()),
            (
                i64::try_from(seconds).expect("fixture fits i64"),
                nanos,
                time::UtcOffset::UTC
            )
        );
    }
}

#[test]
#[should_panic(expected = "system time before Unix epoch")]
fn cache_clock_rejects_pre_epoch_system_time() {
    let before_epoch = UNIX_EPOCH - Duration::from_secs(1);
    cache_now_utc(before_epoch.duration_since(UNIX_EPOCH));
}

#[test]
#[should_panic(expected = "system time outside timestamp range")]
fn cache_clock_rejects_original_calendar_overflow() {
    cache_now_utc(Ok(Duration::from_secs(8_210_266_876_800)));
}

#[test]
fn cache_clock_preserves_original_seconds_cast() {
    let now = cache_now_utc(Ok(Duration::from_secs(u64::MAX)));
    assert_eq!(
        (now.unix_timestamp(), now.nanosecond(), now.offset()),
        (-1, 0, time::UtcOffset::UTC)
    );
}
